<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {useWorkbench} from '../stores/workbench'
import {uid,blockingReasons} from '../lib/domain'
import type {VisualNeed,VisualBatch} from '../lib/visual-candidates'
const props=defineProps<{projectId:string;need:VisualNeed;batches:VisualBatch[]}>()
const store=useWorkbench(),ready=ref<{online:boolean;message:string;supportsSeed?:boolean}>({online:false,message:'正在检查执行端'}),jobs=ref<Job[]>([]),batchId=ref(''),count=ref(4),maxCost=ref(0),seed=ref(''),busy=ref(false),error=ref('')
interface Job {id:string;needId:string;batchId:string;state:string;error?:string;seed?:number}
const labels:Record<string,string>={QUEUED:'排队中',SUBMITTING:'正在提交',SUBMITTED:'已受理',RUNNING:'生成中',UNKNOWN:'受理情况未知',COLLECTION_FAILED:'原件回收失败',CANCEL_REQUESTED:'等待取消确认',CANCELLED:'已取消',FAILED:'失败',SUCCEEDED:'候选已入库'}
const relevant=computed(()=>jobs.value.filter(j=>j.needId===props.need.id)),project=computed(()=>store.state.projects.find(p=>p.id===props.projectId)),reasons=computed(()=>{const node=store.catalog.nodes.find(n=>n.id===props.need.productionNodeId);return project.value&&node?blockingReasons(project.value,node,store.catalog):['请先将需求归类到主体内容或辅助画面']})
let timer:ReturnType<typeof setInterval>,polling=false,disposed=false,epoch=0
async function api<T>(path:string,body?:object):Promise<T>{const r=await fetch('/api/v1/visual-jobs'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});const v=await r.json();if(!r.ok)throw new Error(v.message??'生成任务请求失败');return v.data}
watch(()=>[props.projectId,props.need.id,props.batches[0]?.id],()=>{batchId.value=props.batches[0]?.id??'';epoch++;void refresh()})
async function refresh(){if(polling||disposed)return;if(store.connection!=='server'){ready.value={online:false,message:'生成任务需要后端服务，可先手工导入候选'};jobs.value=[];return}polling=true;const generation=epoch,id=props.projectId;try{const [r,list]=await Promise.all([api<typeof ready.value>('/readiness'),api<Job[]>('?projectId='+encodeURIComponent(id))]);if(disposed||generation!==epoch)return;const changed=list.some(j=>j.state==='SUCCEEDED'&&jobs.value.find(old=>old.id===j.id)?.state!=='SUCCEEDED');ready.value=r;jobs.value=list;if(changed)await store.init();error.value=''}catch(e){if(!disposed&&generation===epoch){ready.value={online:false,message:'执行端暂不可用'};error.value=(e as Error).message}}finally{polling=false}}
async function generate(){if(!batchId.value)return;busy.value=true;try{await api('',{id:uid('draw'),projectId:props.projectId,batchId:batchId.value,count:count.value,maxCostCents:Math.round(maxCost.value*100),expectedVersion:store.state.version,...(seed.value!==''?{seedStart:Number(seed.value)}:{})});store.toast('生成任务已排队；结果会进入候选区，等待你筛选');await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function control(job:Job,action:string){busy.value=true;try{await api('/'+job.id+'/control',{action});await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>{batchId.value=props.batches[0]?.id??'';void refresh();timer=setInterval(()=>{if(!document.hidden)void refresh()},5000)})
onBeforeUnmount(()=>{disposed=true;epoch++;clearInterval(timer)})
</script>
<template><section class="generation-panel" aria-label="生成与重抽"><div class="generation-heading"><h3>生成候选</h3><span class="badge neutral">{{ready.online?'执行端在线':'执行端未连接'}}</span></div><p>{{ready.message}}。生成结果不会自动替换当前采用。</p><form class="generation-form" @submit.prevent="generate"><label>本次生成批次<select v-model="batchId" required aria-label="本次生成批次"><option value="">先建立候选批次</option><option v-for="b in batches" :key="b.id" :value="b.id">{{b.mediaKind==='IMAGE'?'图片':'视频'}} · {{b.modelSnapshot.name}}</option></select></label><label>候选数量<input v-model.number="count" type="number" min="1" max="8" required></label><label>每条费用预留（元）<input v-model.number="maxCost" type="number" min="0" step="0.01" required></label><label v-if="ready.supportsSeed">起始 seed（可选）<input v-model="seed" type="number" min="0" max="2147483639"></label><button class="btn primary" :disabled="busy||!ready.online||!batchId||!!reasons.length||!need.productionNodeId">生成候选</button></form><p class="small">沿用原批次可继续抽取；改变提示词、参考图或模型时建立下一批。费用预留用于本系统排队控制，实际费用由执行端报告。</p><p v-if="reasons.length" class="generation-message">{{reasons[0]}}</p><p v-if="error" role="alert" class="generation-message">{{error}}</p><details v-if="relevant.length" open><summary>本画面的生成任务 · {{relevant.length}}</summary><ol class="generation-jobs"><li v-for="job in relevant" :key="job.id"><div><b>{{labels[job.state]??job.state}}</b><small>{{job.id}}{{job.seed!==undefined?' · seed '+job.seed:''}}</small><p v-if="job.error">{{job.error}}</p></div><button v-if="['UNKNOWN','COLLECTION_FAILED','SUBMITTING'].includes(job.state)" class="btn" :disabled="busy" @click="control(job,'RECOVER')">查询原任务</button><button v-if="!['SUCCEEDED','FAILED','CANCELLED','CANCEL_REQUESTED'].includes(job.state)" class="text-link" :disabled="busy" @click="control(job,'CANCEL')">取消</button></li></ol></details></section></template>
<style scoped>
.generation-panel{margin:22px 0;padding:18px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.generation-heading{display:flex;gap:16px;align-items:center;justify-content:space-between}.generation-heading h3{margin:0;font-size:17px}.generation-panel p{font-size:13px;line-height:1.7;color:#555d6c;margin:10px 0}.generation-form{display:flex;flex-wrap:wrap;gap:12px;align-items:end;margin:16px 0}.generation-form label{display:grid;gap:7px;font-size:12px;flex:1 1 120px;min-width:0}.generation-form label:first-child{flex-basis:200px}.generation-form select,.generation-form input{width:100%;min-width:0}.generation-message{color:#8b402d!important}.generation-jobs{list-style:none;padding:0;margin:12px 0}.generation-jobs li{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);font-size:13px}.generation-jobs li>div{flex:1;min-width:0}.generation-jobs small{display:block;font-size:11px;color:#555d6c;overflow-wrap:anywhere;margin-top:5px}.generation-jobs li p{margin-bottom:0}.generation-panel summary{cursor:pointer;font-size:13px}@media(max-width:700px){.generation-jobs li{flex-wrap:wrap}.generation-heading{align-items:start}.generation-form .btn{width:100%}}
</style>
